class LookupKey:
    __slots__ = ('data',)

    data: Sequence[
        tuple[
            ASTNestedNameElement,
            ASTTemplateParams | ASTTemplateIntroduction,
            str | None,
        ]
    ]

    def __init__(
        self,
        data: Sequence[
            tuple[
                ASTNestedNameElement,
                ASTTemplateParams | ASTTemplateIntroduction,
                str | None,
            ]
        ],
        /,
    ) -> None:
        self.data = data

    def __repr__(self) -> str:
        return f'LookupKey({self.data!r})'

    def __str__(self) -> str:
        inner = ', '.join(f'({ident}, {id_})' for ident, _, id_ in self.data)
        return f'[{inner}]'


def _is_specialization(
    template_params: ASTTemplateParams | ASTTemplateIntroduction,
    template_args: ASTTemplateArgs,
) -> bool:
    # Checks if `template_args` does not exactly match `template_params`.
    # the names of the template parameters must be given exactly as args
    # and params that are packs must in the args be the name expanded
    if len(template_params.params) != len(template_args.args):
        return True
    # having no template params and no arguments is also a specialization
    if len(template_params.params) == 0:
        return True
    for i in range(len(template_params.params)):
        param = template_params.params[i]
        arg = template_args.args[i]
        # TODO: doing this by string manipulation is probably not the most efficient
        param_name = str(param.name)
        arg_txt = str(arg)
        is_arg_pack_expansion = arg_txt.endswith('...')
        if param.isPack != is_arg_pack_expansion:
            return True
        arg_name = arg_txt[:-3] if is_arg_pack_expansion else arg_txt
        if param_name != arg_name:
            return True
    return False


class Symbol:
    debug_indent = 0
    debug_indent_string = '  '
    debug_lookup = False  # overridden by the corresponding config value
    debug_show_tree = False  # overridden by the corresponding config value

    def __copy__(self) -> NoReturn:
        raise AssertionError  # shouldn't happen

    def __deepcopy__(self, memo: Any) -> Symbol:
        if self.parent:
            raise AssertionError  # shouldn't happen
        # the domain base class makes a copy of the initial data, which is fine
        return Symbol(None, None, None, None, None, None, None)

    @staticmethod
    def debug_print(*args: Any) -> None:
        logger.debug(Symbol.debug_indent_string * Symbol.debug_indent, end='')
        logger.debug(*args)

    def _assert_invariants(self) -> None:
        if not self.parent:
            # parent == None means global scope, so declaration means a parent
            assert not self.identOrOp
            assert not self.templateParams
            assert not self.templateArgs
            assert not self.declaration
            assert not self.docname
        else:
            if self.declaration:
                assert self.docname

    def __setattr__(self, key: str, value: Any) -> None:
        if key == 'children':
            raise AssertionError
        return super().__setattr__(key, value)

    def __init__(
        self,
        parent: Symbol | None,
        identOrOp: ASTIdentifier | ASTOperator | None,
        templateParams: ASTTemplateParams | ASTTemplateIntroduction | None,
        templateArgs: Any,
        declaration: ASTDeclaration | None,
        docname: str | None,
        line: int | None,
    ) -> None:
        self.parent = parent
        # declarations in a single directive are linked together
        self.siblingAbove: Symbol | None = None
        self.siblingBelow: Symbol | None = None
        self.identOrOp = identOrOp
        # Ensure the same symbol for `A` is created for:
        #
        #     .. cpp:class:: template <typename T> class A
        #
        # and
        #
        #     .. cpp:function:: template <typename T> int A<T>::foo()
        if templateArgs is not None and not _is_specialization(
            templateParams, templateArgs
        ):
            templateArgs = None
        self.templateParams = templateParams  # template<templateParams>
        self.templateArgs = templateArgs  # identifier<templateArgs>
        self.declaration = declaration
        self.docname = docname
        self.line = line
        self.isRedeclaration = False
        self._assert_invariants()

        # Remember to modify Symbol.remove if modifications to the parent change.
        self._children: list[Symbol] = []
        self._anon_children: list[Symbol] = []
        # note: _children includes _anon_children
        if self.parent:
            self.parent._children.append(self)
        if self.declaration:
            self.declaration.symbol = self

        # Do symbol addition after self._children has been initialised.
        self._add_template_and_function_params()

    def __repr__(self) -> str:
        return f'<Symbol {self.to_string(indent=0)!r}>'

    def _fill_empty(self, declaration: ASTDeclaration, docname: str, line: int) -> None:
        self._assert_invariants()
        assert self.declaration is None
        assert self.docname is None
        assert self.line is None
        assert declaration is not None
        assert docname is not None
        assert line is not None
        self.declaration = declaration
        self.declaration.symbol = self
        self.docname = docname
        self.line = line
        self._assert_invariants()
        # and symbol addition should be done as well
        self._add_template_and_function_params()

    def _add_template_and_function_params(self) -> None:
        if Symbol.debug_lookup:
            Symbol.debug_indent += 1
            Symbol.debug_print('_add_template_and_function_params:')
        # Note: we may be called from _fill_empty, so the symbols we want
        #       to add may actually already be present (as empty symbols).

        # add symbols for the template params
        if self.templateParams:
            for tp in self.templateParams.params:
                if not tp.get_identifier():
                    continue
                # only add a declaration if we our self are from a declaration
                if self.declaration:
                    decl = ASTDeclaration(objectType='templateParam', declaration=tp)
                else:
                    decl = None
                nne = ASTNestedNameElement(tp.get_identifier(), None)
                nn = ASTNestedName([nne], [False], rooted=False)
                self._add_symbols(nn, [], decl, self.docname, self.line)
        # add symbols for function parameters, if any
        if (
            self.declaration is not None
            and self.declaration.function_params is not None
        ):
            for fp in self.declaration.function_params:
                if fp.arg is None:
                    continue
                nn = fp.arg.name
                if nn is None:
                    continue
                # (comparing to the template params: we have checked that we are a declaration)
                decl = ASTDeclaration(objectType='functionParam', declaration=fp)
                assert not nn.rooted
                assert len(nn.names) == 1
                self._add_symbols(nn, [], decl, self.docname, self.line)
        if Symbol.debug_lookup:
            Symbol.debug_indent -= 1

    def remove(self) -> None:
        if self.parent is None:
            return
        assert self in self.parent._children
        self.parent._children.remove(self)
        self.parent = None

    def clear_doc(self, docname: str) -> None:
        new_children: list[Symbol] = []
        for s_child in self._children:
            s_child.clear_doc(docname)
            if s_child.declaration and s_child.docname == docname:
                s_child.declaration = None
                s_child.docname = None
                s_child.line = None
                if s_child.siblingAbove is not None:
                    s_child.siblingAbove.siblingBelow = s_child.siblingBelow
                if s_child.siblingBelow is not None:
                    s_child.siblingBelow.siblingAbove = s_child.siblingAbove
                s_child.siblingAbove = None
                s_child.siblingBelow = None
            new_children.append(s_child)
        self._children = new_children

    def get_all_symbols(self) -> Iterator[Any]:
        yield self
        for s_child in self._children:
            yield from s_child.get_all_symbols()

    @property
    def children_recurse_anon(self) -> Iterator[Symbol]:
        for c in self._children:
            yield c
            if not c.identOrOp.is_anon():
                continue

            yield from c.children_recurse_anon

    def get_lookup_key(self) -> LookupKey:
        # The pickle files for the environment and for each document are distinct.
        # The environment has all the symbols, but the documents has xrefs that
        # must know their scope. A lookup key is essentially a specification of
        # how to find a specific symbol.
        symbols = []
        s = self
        while s.parent:
            symbols.append(s)
            s = s.parent
        key = [
            (
                ASTNestedNameElement(s.identOrOp, s.templateArgs),
                s.templateParams,
                None if s.declaration is None else s.declaration.get_newest_id(),
            )
            for s in reversed(symbols)
        ]
        return LookupKey(key)

    def get_full_nested_name(self) -> ASTNestedName:
        symbols = []
        s = self
        while s.parent:
            symbols.append(s)
            s = s.parent
        symbols.reverse()
        names = []
        templates = []
        for s in symbols:
            names.append(ASTNestedNameElement(s.identOrOp, s.templateArgs))
            templates.append(False)

        if Symbol.debug_lookup:
            Symbol.debug_indent -= 2
        return symbol

    if Symbol.debug_lookup:
        Symbol.debug_print('_add_symbols, result, symbols:')
        Symbol.debug_indent += 1
        Symbol.debug_print('number symbols:', len(symbols))
        Symbol.debug_indent -= 1

    if not declaration:
        if Symbol.debug_lookup:
            Symbol.debug_print('no declaration')
            Symbol.debug_indent -= 2
        # good, just a scope creation
        # TODO: what if we have more than one symbol?
        return symbols[0]

    no_decl = []
    with_decl = []
    dup_decl = []
    for s in symbols:
        if s.declaration is None:
            no_decl.append(s)
        elif s.isRedeclaration:
            dup_decl.append(s)
        else:
            with_decl.append(s)
    if Symbol.debug_lookup:
        Symbol.debug_print('#no_decl:  ', len(no_decl))
        Symbol.debug_print('#with_decl:', len(with_decl))
        Symbol.debug_print('#dup_decl: ', len(dup_decl))
    # With partial builds we may start with a large symbol tree stripped of declarations.
    # Essentially any combination of no_decl, with_decl, and dup_decls seems possible.
    # TODO: make partial builds fully work. What should happen when the primary symbol gets
    #  deleted, and other duplicates exist? The full document should probably be rebuild.

    # First check if one of those with a declaration matches.
    # If it's a function, we need to compare IDs,
    # otherwise there should be only one symbol with a declaration.
    if len(with_decl) == 0:
        cand_symbol = None
    else:
        cand_symbol = self._make_cand_symbol(
            lookup_result, declaration, docname, line
        )

        if declaration.objectType != 'function':
            assert len(with_decl) <= 1
            self._handle_duplicate_declaration(
                with_decl[0], cand_symbol, declaration
            )
            # (not reachable)

        # a function, so compare IDs
        cand_id = declaration.get_newest_id()
        if Symbol.debug_lookup:
            Symbol.debug_print('cand_id:', cand_id)
        for symbol in with_decl:
            # but all existing must be functions as well,
            # otherwise we declare it to be a duplicate
            if symbol.declaration.objectType != 'function':
                self._handle_duplicate_declaration(symbol, cand_symbol, declaration)
                # (not reachable)
            old_id = symbol.declaration.get_newest_id()
            if Symbol.debug_lookup:
                Symbol.debug_print('old_id: ', old_id)
            if cand_id == old_id:
                self._handle_duplicate_declaration(symbol, cand_symbol, declaration)
                # (not reachable)
        # no candidate symbol found with matching ID
    # if there is an empty symbol, fill that one
    if len(no_decl) == 0:
        if Symbol.debug_lookup:
            Symbol.debug_print('no match, no empty')
            if cand_symbol is not None:
                Symbol.debug_print('result is already created cand_symbol')
            else:
                Symbol.debug_print('result is self._make_cand_symbol()')
            Symbol.debug_indent -= 2
        if cand_symbol is not None:
            return cand_symbol
        else:
            return self._make_cand_symbol(lookup_result, declaration, docname, line)
    else:
        if Symbol.debug_lookup:
            Symbol.debug_print(
                'no match, but fill an empty declaration, cand_sybmol is not None?:',
                cand_symbol is not None,
            )
            Symbol.debug_indent -= 2
        if cand_symbol is not None:
            cand_symbol.remove()
        # assert len(no_decl) == 1
        # TODO: enable assertion when we at some point find out how to do cleanup
        # for now, just take the first one, it should work fine ... right?
        symbol = no_decl[0]
        # If someone first opened the scope, and then later
        # declares it, e.g,
        # .. namespace:: Test
        # .. namespace:: nullptr
        # .. class:: Test
        symbol._fill_empty(declaration, docname, line)
        return symbol

@staticmethod
def _make_cand_symbol(
    lookup_result: SymbolLookupResult,
    declaration: ASTDeclaration | None,
    docname: str | None,
    line: int | None,
) -> Symbol:
    if Symbol.debug_lookup:
        Symbol.debug_print('begin: creating candidate symbol')
    symbol = Symbol(
        parent=lookup_result.parent_symbol,
        identOrOp=lookup_result.ident_or_op,
        templateParams=lookup_result.template_params,
        templateArgs=lookup_result.template_args,
        declaration=declaration,
        docname=docname,
        line=line,
    )
    if Symbol.debug_lookup:
        Symbol.debug_print('end:   creating candidate symbol')
    return symbol

@staticmethod
def _handle_duplicate_declaration(
    symbol: Symbol, cand_symbol: Symbol, declaration: ASTDeclaration
) -> None:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('redeclaration')
        Symbol.debug_indent -= 1
        Symbol.debug_indent -= 2
    # Redeclaration of the same symbol.
    # Let the new one be there, but raise an error to the client
    # so it can use the real symbol as subscope.
    # This will probably result in a duplicate id warning.
    cand_symbol.isRedeclaration = True
    raise _DuplicateSymbolError(symbol, declaration)

def merge_with(
    self, other: Symbol, docnames: list[str], env: BuildEnvironment
) -> None:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('merge_with:')
    assert other is not None

    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
    for other_child in other._children:
        if Symbol.debug_lookup:
            Symbol.debug_print(
                'other_child:\n', other_child.to_string(Symbol.debug_indent)
            )
            Symbol.debug_indent += 1
        if other_child.isRedeclaration:
            self._unconditional_add(other_child)
            if Symbol.debug_lookup:
                Symbol.debug_print('is_redeclaration')
                Symbol.debug_indent -= 1
            continue
        candiate_iter = self._find_named_symbols(
            ident_or_op=other_child.identOrOp,
            template_params=other_child.templateParams,
            template_args=other_child.templateArgs,
            template_shorthand=False,
            match_self=False,
            recurse_in_anon=False,
            correct_primary_template_args=False,
            search_in_siblings=False,
        )
        candidates = list(candiate_iter)

        if Symbol.debug_lookup:
            Symbol.debug_print('raw candidate symbols:', len(candidates))
        symbols = [s for s in candidates if not s.isRedeclaration]
        if Symbol.debug_lookup:
            Symbol.debug_print('non-duplicate candidate symbols:', len(symbols))

        if len(symbols) == 0:
            self._unconditional_add(other_child)
            if Symbol.debug_lookup:
                Symbol.debug_indent -= 1
            continue

        our_child = None
        if other_child.declaration is None:
            if Symbol.debug_lookup:
                Symbol.debug_print('no declaration in other child')
            our_child = symbols[0]
        else:
            query_id = other_child.declaration.get_newest_id()
            if Symbol.debug_lookup:
                Symbol.debug_print('query_id:  ', query_id)
            for symbol in symbols:
                if symbol.declaration is None:
                    if Symbol.debug_lookup:
                        Symbol.debug_print('empty candidate')
                    # if in the end we have non-matching, but have an empty one,
                    # then just continue with that
                    our_child = symbol
                    continue
                cand_id = symbol.declaration.get_newest_id()
                if Symbol.debug_lookup:
                    Symbol.debug_print('candidate:', cand_id)
                if cand_id == query_id:
                    our_child = symbol
                    break
        if Symbol.debug_lookup:
            Symbol.debug_indent -= 1
        if our_child is None:
            self._unconditional_add(other_child)
            continue
        if other_child.declaration and other_child.docname in docnames:
            if not our_child.declaration:
                our_child._fill_empty(
                    other_child.declaration, other_child.docname, other_child.line
                )
            elif our_child.docname != other_child.docname:
                name = str(our_child.declaration)
                msg = __(
                    'Duplicate C++ declaration, also defined at %s:%s.\n'
                    "Declaration is '.. cpp:%s:: %s'."
                )
                logger.warning(
                    msg,
                    our_child.docname,
                    our_child.line,
                    our_child.declaration.directiveType,
                    name,
                    location=(other_child.docname, other_child.line),
                    type='duplicate_declaration',
                    subtype='cpp',
                )
            else:
                our_object_type = our_child.declaration.objectType
                other_object_type = other_child.declaration.objectType
                our_child_parent_decl = our_child.parent.declaration
                other_child_parent_decl = other_child.parent.declaration
                if (
                    other_object_type == our_object_type
                    and other_object_type in {'templateParam', 'functionParam'}
                    and our_child_parent_decl == other_child_parent_decl
                ):
                    # `our_child` was just created during merging by the call
                    # to `_fill_empty` on the parent and can be ignored.
                    pass
                else:
                    # Both have declarations, and in the same docname.
                    # This can apparently happen, it should be safe to
                    # just ignore it, right?
                    # Hmm, only on duplicate declarations, right?
                    msg = 'Internal C++ domain error during symbol merging.\n'
                    msg += 'our_child:\n' + our_child.to_string(1)
                    msg += '\nother_child:\n' + other_child.to_string(1)
                    logger.warning(msg, location=other_child.docname)
        our_child.merge_with(other_child, docnames, env)
    if Symbol.debug_lookup:
        Symbol.debug_indent -= 2

def _unconditional_add(self, other_child: Symbol) -> None:
    # TODO: hmm, should we prune by docnames?
    self._children.append(other_child)
    other_child.parent = self
    other_child._assert_invariants()

def add_name(
    self,
    nestedName: ASTNestedName,
    templatePrefix: ASTTemplateDeclarationPrefix | None = None,
) -> Symbol:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('add_name:')
    if templatePrefix:
        template_decls = templatePrefix.templates
    else:
        template_decls = []
    res = self._add_symbols(
        nestedName, template_decls, declaration=None, docname=None, line=None
    )
    if Symbol.debug_lookup:
        Symbol.debug_indent -= 1
    return res

def add_declaration(
    self, declaration: ASTDeclaration, docname: str, line: int
) -> Symbol:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('add_declaration:')
    assert declaration is not None
    assert docname is not None
    assert line is not None
    nested_name = declaration.name
    if declaration.templatePrefix:
        template_decls = declaration.templatePrefix.templates
    else:
        template_decls = []
    res = self._add_symbols(nested_name, template_decls, declaration, docname, line)
    if Symbol.debug_lookup:
        Symbol.debug_indent -= 1
    return res

def find_identifier(
    self,
    identOrOp: ASTIdentifier | ASTOperator,
    matchSelf: bool,
    recurseInAnon: bool,
    searchInSiblings: bool,
) -> Symbol | None:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('find_identifier:')
        Symbol.debug_indent += 1
        Symbol.debug_print('identOrOp:       ', identOrOp)
        Symbol.debug_print('matchSelf:       ', matchSelf)
        Symbol.debug_print('recurseInAnon:   ', recurseInAnon)
        Symbol.debug_print('searchInSiblings:', searchInSiblings)
        logger.debug(self.to_string(Symbol.debug_indent + 1), end='')
        Symbol.debug_indent -= 2
    current = self
    while current is not None:
        if Symbol.debug_lookup:
            Symbol.debug_indent += 2
            Symbol.debug_print('trying:')
            logger.debug(current.to_string(Symbol.debug_indent + 1), end='')
            Symbol.debug_indent -= 2
        if matchSelf and current.identOrOp == identOrOp:
            return current
        if recurseInAnon:
            children: Iterable[Symbol] = current.children_recurse_anon
        else:
            children = current._children
        for s in children:
            if s.identOrOp == identOrOp:
                return s
        if not searchInSiblings:
            break
        current = current.siblingAbove
    return None

def direct_lookup(self, key: LookupKey) -> Symbol:
    if Symbol.debug_lookup:
        Symbol.debug_indent += 1
        Symbol.debug_print('direct_lookup:')
        Symbol.debug_indent += 1
    s = self
    for name, template_params, id_ in key.data:
        if id_ is not None:
            res = None
            for cand in s._children:
                if cand.declaration is None:
                    continue
                if cand.declaration.get_newest_id() == id_:
                    res = cand

        if not self.match(udl_identifier_re):
            return literal
        # hmm, should we care if it's a keyword?
        # it looks like GCC does not disallow keywords
        ident = ASTIdentifier(self.matched_text)
        return ASTUserDefinedLiteral(literal, ident)

    self.skip_ws()
    if self.skip_word('nullptr'):
        return ASTPointerLiteral()
    if self.skip_word('true'):
        return ASTBooleanLiteral(True)
    if self.skip_word('false'):
        return ASTBooleanLiteral(False)
    pos = self.pos
    if self.match(float_literal_re):
        has_suffix = self.match(float_literal_suffix_re)
        float_lit = ASTNumberLiteral(self.definition[pos : self.pos])
        if has_suffix:
            return float_lit
        else:
            return _udl(float_lit)
    for regex in (
        binary_literal_re,
        hex_literal_re,
        integer_literal_re,
        octal_literal_re,
    ):
        if self.match(regex):
            has_suffix = self.match(integers_literal_suffix_re)
            int_lit = ASTNumberLiteral(self.definition[pos : self.pos])
            if has_suffix:
                return int_lit
            else:
                return _udl(int_lit)

    string = self._parse_string()
    if string is not None:
        return _udl(ASTStringLiteral(string))

    # character-literal
    if self.match(char_literal_re):
        prefix = self.last_match.group(1)  # may be None when no prefix
        data = self.last_match.group(2)
        try:
            char_lit = ASTCharLiteral(prefix, data)
        except UnicodeDecodeError as e:
            self.fail(
                'Can not handle character literal. Internal error was: %s' % e
            )
        except UnsupportedMultiCharacterCharLiteral:
            self.fail(
                'Can not handle character literal'
                ' resulting in multiple decoded characters.'
            )
        return _udl(char_lit)
    return None

def _parse_fold_or_paren_expression(self) -> ASTExpression | None:
    # "(" expression ")"
    # fold-expression
    # -> ( cast-expression fold-operator ... )
    #  | ( ... fold-operator cast-expression )
    #  | ( cast-expression fold-operator ... fold-operator cast-expression
    if self.current_char != '(':
        return None
    self.pos += 1
    self.skip_ws()
    if self.skip_string_and_ws('...'):
        # ( ... fold-operator cast-expression )
        if not self.match(_fold_operator_re):
            self.fail("Expected fold operator after '...' in fold expression.")
        op = self.matched_text
        right_expr = self._parse_cast_expression()
        if not self.skip_string(')'):
            self.fail("Expected ')' in end of fold expression.")
        return ASTFoldExpr(None, op, right_expr)
    # try first parsing a unary right fold, or a binary fold
    pos = self.pos
    try:
        self.skip_ws()
        left_expr = self._parse_cast_expression()
        self.skip_ws()
        if not self.match(_fold_operator_re):
            self.fail(
                'Expected fold operator after left expression in fold expression.'
            )
        op = self.matched_text
        self.skip_ws()
        if not self.skip_string_and_ws('...'):
            self.fail("Expected '...' after fold operator in fold expression.")
    except DefinitionError as e_fold:
        self.pos = pos
        # fall back to a paren expression
        try:
            res = self._parse_expression()
            self.skip_ws()
            if not self.skip_string(')'):
                self.fail("Expected ')' in end of parenthesized expression.")
        except DefinitionError as e_expr:
            raise self._make_multi_error(
                [
                    (e_fold, 'If fold expression'),
                    (e_expr, 'If parenthesized expression'),
                ],
                'Error in fold expression or parenthesized expression.',
            ) from e_expr
        return ASTParenExpr(res)
    # now it definitely is a fold expression
    if self.skip_string(')'):
        return ASTFoldExpr(left_expr, op, None)
    if not self.match(_fold_operator_re):
        self.fail("Expected fold operator or ')' after '...' in fold expression.")
    if op != self.matched_text:
        self.fail(
            "Operators are different in binary fold: '%s' and '%s'."
            % (op, self.matched_text)
        )
    right_expr = self._parse_cast_expression()
    self.skip_ws()
    if not self.skip_string(')'):
        self.fail("Expected ')' to end binary fold expression.")
    return ASTFoldExpr(left_expr, op, right_expr)

def _parse_primary_expression(self) -> ASTExpression:
    # literal
    # "this"
    # lambda-expression
    # "(" expression ")"
    # fold-expression
    # id-expression -> we parse this with _parse_nested_name
    self.skip_ws()
    res: ASTExpression = self._parse_literal()
    if res is not None:
        return res
    self.skip_ws()
    if self.skip_word('this'):
        return ASTThisLiteral()
    # TODO: try lambda expression
    res = self._parse_fold_or_paren_expression()
    if res is not None:
        return res
    nn = self._parse_nested_name()
    if nn is not None:
        return ASTIdExpression(nn)
    return None

def _parse_initializer_list(
    self, name: str, open: str, close: str
) -> tuple[list[ASTExpression | ASTBracedInitList], bool]:
    # Parse open and close with the actual initializer-list in between
    # -> initializer-clause '...'[opt]
    #  | initializer-list ',' initializer-clause '...'[opt]
    self.skip_ws()
    if not self.skip_string_and_ws(open):
        return None, None
    if self.skip_string(close):
        return [], False

    exprs: list[ASTExpression | ASTBracedInitList] = []
    trailing_comma = False
    while True:
        self.skip_ws()
        expr = self._parse_initializer_clause()
        self.skip_ws()
        if self.skip_string('...'):
            exprs.append(ASTPackExpansionExpr(expr))
        else:
            exprs.append(expr)
        self.skip_ws()
        if self.skip_string(close):
            break
        if not self.skip_string_and_ws(','):
            self.fail(f"Error in {name}, expected ',' or '{close}'.")
        if self.current_char == close == '}':
            self.pos += 1
            trailing_comma = True
            break
    return exprs, trailing_comma

def _parse_paren_expression_list(self) -> ASTParenExprList:
    # -> '(' expression-list ')'
    # though, we relax it to also allow empty parens
    # as it's needed in some cases
    #
    # expression-list
    # -> initializer-list
    exprs, _trailing_comma = self._parse_initializer_list(
        'parenthesized expression-list', '(', ')'
    )
    if exprs is None:
        return None
    return ASTParenExprList(exprs)

def _parse_initializer_clause(self) -> ASTExpression | ASTBracedInitList:
    braced_init_list = self._parse_braced_init_list()
    if braced_init_list is not None:
        return braced_init_list
    return self._parse_assignment_expression(in_template=False)

def _parse_braced_init_list(self) -> ASTBracedInitList:
    # -> '{' initializer-list ','[opt] '}'
    #  | '{' '}'
    exprs, trailing_comma = self._parse_initializer_list(
        'braced-init-list', '{', '}'
    )
    if exprs is None:
        return None
    return ASTBracedInitList(exprs, trailing_comma)

def _parse_expression_list_or_braced_init_list(
    self,
) -> ASTParenExprList | ASTBracedInitList:
    paren = self._parse_paren_expression_list()
    if paren is not None:
        return paren
    return self._parse_braced_init_list()

def _parse_postfix_expression(self) -> ASTPostfixExpr:
    # -> primary
    #  | postfix "[" expression "]"
    #  | postfix "[" braced-init-list [opt] "]"
    #  | postfix "(" expression-list [opt] ")"
    #  | postfix "." "template" [opt] id-expression
    #  | postfix "->" "template" [opt] id-expression
    #  | postfix "." pseudo-destructor-name
    #  | postfix "->" pseudo-destructor-name
    #  | postfix "++"
    #  | postfix "--"
    #  | simple-type-specifier "(" expression-list [opt] ")"
    #  | simple-type-specifier braced-init-list
    #  | typename-specifier "(" expression-list [opt] ")"
    #  | typename-specifier braced-init-list
    #  | "dynamic_cast" "<" type-id ">" "(" expression ")"
    #  | "static_cast" "<" type-id ">" "(" expression ")"
    #  | "reinterpret_cast" "<" type-id ">" "(" expression ")"
    #  | "const_cast" "<" type-id ">" "(" expression ")"
    #  | "typeid" "(" expression ")"
    #  | "typeid" "(" type-id ")"

    prefix_type = None
    prefix: Any = None
    self.skip_ws()

    cast = None
    for c in _id_explicit_cast:
        if self.skip_word_and_ws(c):
            cast = c
            break
    if cast is not None:
        prefix_type = 'cast'
        if not self.skip_string('<'):
            self.fail("Expected '<' after '%s'." % cast)
        typ = self._parse_type(False)
        self.skip_ws()
        if not self.skip_string_and_ws('>'):
            self.fail("Expected '>' after type in '%s'." % cast)
        if not self.skip_string('('):
            self.fail("Expected '(' in '%s'." % cast)

        parser = self._parse_expression
        expr = self._parse_expression_fallback([')'], parser)
        self.skip_ws()
        if not self.skip_string(')'):
            self.fail("Expected ')' to end '%s'." % cast)
        prefix = ASTExplicitCast(cast, typ, expr)
    elif self.skip_word_and_ws('typeid'):
        prefix_type = 'typeid'
        if not self.skip_string_and_ws('('):
            self.fail("Expected '(' after 'typeid'.")
        pos = self.pos
        try:
            typ = self._parse_type(False)
            prefix = ASTTypeId(typ, isType=True)
            if not self.skip_string(')'):
                self.fail("Expected ')' to end 'typeid' of type.")
        except DefinitionError as e_type:
            self.pos = pos
            try:
                parser = self._parse_expression
                expr = self._parse_expression_fallback([')'], parser)
                prefix = ASTTypeId(expr, isType=False)
                if not self.skip_string(')'):
                    self.fail("Expected ')' to end 'typeid' of expression.")
            except DefinitionError as e_expr:
                self.pos = pos
                header = "Error in 'typeid(...)'."
                header += ' Expected type or expression.'
                errors = [
                    (e_type, 'If type'),
                    (e_expr, 'If expression'),
                ]
                raise self._make_multi_error(errors, header) from e_expr
    else:  # a primary expression or a type
        pos = self.pos
        try:
            prefix = self._parse_primary_expression()
            prefix_type = 'expr'
        except DefinitionError as e_outer:
            self.pos = pos
            try:
                # we are potentially casting, so save parens for us
                # TODO: hmm, would we need to try both with operatorCast and with None?
                prefix = self._parse_type(False, 'operatorCast')
                prefix_type = 'typeOperatorCast'
                #  | simple-type-specifier "(" expression-list [opt] ")"
                #  | simple-type-specifier braced-init-list
                #  | typename-specifier "(" expression-list [opt] ")"
                #  | typename-specifier braced-init-list
                self.skip_ws()
                if self.current_char not in {'(', '{'}:
                    self.fail("Expecting '(' or '{' after type in cast expression.")
            except DefinitionError as e_inner:
                self.pos = pos
                header = 'Error in postfix expression,'
                header += ' expected primary expression or type.'
                errors = [
                    (e_outer, 'If primary expression'),
                    (e_inner, 'If type'),
                ]
                raise self._make_multi_error(errors, header) from e_inner

    # and now parse postfixes
    post_fixes: list[ASTPostfixOp] = []
    while True:
        self.skip_ws()
        if prefix_type in {'expr', 'cast', 'typeid'}:
            if self.skip_string_and_ws('['):
                expr = self._parse_expression()
                self.skip_ws()
                if not self.skip_string(']'):
                    self.fail("Expected ']' in end of postfix expression.")
                post_fixes.append(ASTPostfixArray(expr))
                continue
            if self.skip_string('.'):
                if self.skip_string('*'):
                    # don't steal the dot
                    self.pos -= 2
                elif self.skip_string('..'):
                    # don't steal the dot
                    self.pos -= 3
                else:
                    name = self._parse_nested_name()
                    post_fixes.append(ASTPostfixMember(name))
                    continue
            if self.skip_string('->'):
                if self.skip_string('*'):
                    # don't steal the arrow
                    self.pos -= 3
                else:
                    name = self._parse_nested_name()
                    post_fixes.append(ASTPostfixMemberOfPointer(name))
                    continue
            if self.skip_string('++'):
                post_fixes.append(ASTPostfixInc())
                continue
            if self.skip_string('--'):
                post_fixes.append(ASTPostfixDec())
                continue
        lst = self._parse_expression_list_or_braced_init_list()
        if lst is not None:
            post_fixes.append(ASTPostfixCallExpr(lst))
            continue
        break
    return ASTPostfixExpr(prefix, post_fixes)

def _parse_unary_expression(self) -> ASTExpression:
    # -> postfix
    #  | "++" cast
    #  | "--" cast
    #  | unary-operator cast -> (* | & | + | - | ! | ~) cast
    # The rest:
    #  | "sizeof" unary
    #  | "sizeof" "(" type-id ")"
    #  | "sizeof" "..." "(" identifier ")"
    #  | "alignof" "(" type-id ")"
    #  | noexcept-expression -> noexcept "(" expression ")"
    #  | new-expression
    #  | delete-expression
    self.skip_ws()
    for op in _expression_unary_ops:
        # TODO: hmm, should we be able to backtrack here?
        if op[0] in 'cn':
            res = self.skip_word(op)
        else:
            res = self.skip_string(op)
        if res:
            expr = self._parse_cast_expression()
            return ASTUnaryOpExpr(op, expr)
    if self.skip_word_and_ws('sizeof'):
        if self.skip_string_and_ws('...'):
            if not self.skip_string_and_ws('('):
                self.fail("Expecting '(' after 'sizeof...'.")
            if not self.match(identifier_re):
                self.fail("Expecting identifier for 'sizeof...'.")
            ident = ASTIdentifier(self.matched_text)
            self.skip_ws()
            if not self.skip_string(')'):
                self.fail("Expecting ')' to end 'sizeof...'.")
            return ASTSizeofParamPack(ident)
        if self.skip_string_and_ws('('):
            typ = self._parse_type(named=False)
            self.skip_ws()
            if not self.skip_string(')'):
                self.fail("Expecting ')' to end 'sizeof'.")
            return ASTSizeofType(typ)
        expr = self._parse_unary_expression()
        return ASTSizeofExpr(expr)
    if self.skip_word_and_ws('alignof'):
        if not self.skip_string_and_ws('('):
            self.fail("Expecting '(' after 'alignof'.")
        typ = self._parse_type(named=False)
        self.skip_ws()
        if not self.skip_string(')'):
            self.fail("Expecting ')' to end 'alignof'.")
        return ASTAlignofExpr(typ)
    if self.skip_word_and_ws('noexcept'):
        if not self.skip_string_and_ws('('):
            self.fail("Expecting '(' after 'noexcept'.")
        expr = self._parse_expression()
        self.skip_ws()
        if not self.skip_string(')'):
            self.fail("Expecting ')' to end 'noexcept'.")
        return ASTNoexceptExpr(expr)
    # new-expression
    pos = self.pos
    rooted = self.skip_string('::')
    self.skip_ws()
    if not self.skip_word_and_ws('new'):
        self.pos = pos
    else:
        # new-placement[opt] new-type-id new-initializer[opt]
        # new-placement[opt] ( type-id ) new-initializer[opt]
        is_new_type_id = True
        if self.skip_string_and_ws('('):
            # either this is a new-placement or it's the second production
            # without placement, and it's actually the ( type-id ) part
            self.fail(
                'Sorry, neither new-placement nor parenthesised type-id '
                'in new-epression is supported yet.'

            )
            # set is_new_type_id = False if it's (type-id)
        if is_new_type_id:
            decl_specs = self._parse_decl_specs(outer=None)
            decl = self._parse_declarator(named=False, param_mode='new')
        else:
            self.fail(
                'Sorry, parenthesised type-id in new expression not yet supported.'
            )
        lst = self._parse_expression_list_or_braced_init_list()
        return ASTNewExpr(rooted, is_new_type_id, ASTType(decl_specs, decl), lst)
    # delete-expression
    pos = self.pos
    rooted = self.skip_string('::')
    self.skip_ws()
    if not self.skip_word_and_ws('delete'):
        self.pos = pos
    else:
        array = self.skip_string_and_ws('[')
        if array and not self.skip_string_and_ws(']'):
            self.fail("Expected ']' in array delete-expression.")
        expr = self._parse_cast_expression()
        return ASTDeleteExpr(rooted, array, expr)
    return self._parse_postfix_expression()

def _parse_cast_expression(self) -> ASTExpression:
    # -> unary  | "(" type-id ")" cast
    pos = self.pos
    self.skip_ws()
    if self.skip_string('('):
        try:
            typ = self._parse_type(False)
            if not self.skip_string(')'):
                self.fail("Expected ')' in cast expression.")
            expr = self._parse_cast_expression()
            return ASTCastExpr(typ, expr)
        except DefinitionError as ex_cast:
            self.pos = pos
            try:
                return self._parse_unary_expression()
            except DefinitionError as ex_unary:
                errs = [
                    (ex_cast, 'If type cast expression'),
                    (ex_unary, 'If unary expression'),
                ]
                raise self._make_multi_error(
                    errs, 'Error in cast expression.'
                ) from ex_unary
    else:
        return self._parse_unary_expression()

def _parse_logical_or_expression(self, in_template: bool) -> ASTExpression:
    # logical-or     = logical-and      ||
    # logical-and    = inclusive-or     &&
    # inclusive-or   = exclusive-or     |
    # exclusive-or   = and              ^
    # and            = equality         &
    # equality       = relational       ==, !=
    # relational     = shift            <, >, <=, >=, <=>
    # shift          = additive         <<, >>
    # additive       = multiplicative   +, -
    # multiplicative = pm               *, /, %
    # pm             = cast             .*, ->*
    def _parse_bin_op_expr(
        self: DefinitionParser, op_id: int, in_template: bool
    ) -> ASTExpression:
        if op_id + 1 == len(_expression_bin_ops):

            def parser(in_template: bool) -> ASTExpression:
                return self._parse_cast_expression()

        else:

            def parser(in_template: bool) -> ASTExpression:
                return _parse_bin_op_expr(self, op_id + 1, in_template=in_template)

        exprs = []
        ops = []
        exprs.append(parser(in_template=in_template))
        while True:
            self.skip_ws()
            if in_template and self.current_char == '>':
                break
            pos = self.pos
            one_more = False
            for op in _expression_bin_ops[op_id]:
                if op[0] in 'abcnox':
                    if not self.skip_word(op):
                        continue
                else:
                    if not self.skip_string(op):
                        continue
                if op == self.current_char == '&':
                    # don't split the && 'token'
                    self.pos -= 1
                    # and btw. && has lower precedence, so we are done
                    break
                try:
                    expr = parser(in_template=in_template)
                    exprs.append(expr)
                    ops.append(op)
                    one_more = True
                    break
                except DefinitionError:
                    self.pos = pos
            if not one_more:
                break
        return ASTBinOpExpr(exprs, ops)

    return _parse_bin_op_expr(self, 0, in_template=in_template)

def _parse_conditional_expression_tail(
    self, or_expr_head: ASTExpression, in_template: bool
) -> ASTConditionalExpr | None:
    # Consumes the or_expr_head on success.

    # -> "?" expression ":" assignment-expression
    self.skip_ws()
    if not self.skip_string('?'):
        return None
    then_expr = self._parse_expression()
    self.skip_ws()
    if not self.skip_string(':'):
        self.fail('Expected ":" after then-expression in conditional expression.')
    else_expr = self._parse_assignment_expression(in_template)
    return ASTConditionalExpr(or_expr_head, then_expr, else_expr)

def _parse_assignment_expression(self, in_template: bool) -> ASTExpression:
    # -> conditional-expression
    #  | logical-or-expression assignment-operator initializer-clause
    #  | yield-expression -> "co_yield" assignment-expression
    #                      | "co_yield" braced-init-list
    #  | throw-expression -> "throw" assignment-expression[opt]
    # TODO: yield-expression
    # TODO: throw-expression

    # Now we have (after expanding conditional-expression:
    #     logical-or-expression
    #   | logical-or-expression "?" expression ":" assignment-expression
    #   | logical-or-expression assignment-operator initializer-clause
    left_expr = self._parse_logical_or_expression(in_template=in_template)
    # the ternary operator
    cond_expr = self._parse_conditional_expression_tail(left_expr, in_template)
    if cond_expr is not None:
        return cond_expr
    # and actual assignment
    for op in _expression_assignment_ops:
        if op[0] in 'anox':
            if not self.skip_word(op):
                continue
        else:
            if not self.skip_string(op):
                continue
        right_expr = self._parse_initializer_clause()
        return ASTAssignmentExpr(left_expr, op, right_expr)
    # just a logical-or-expression
    return left_expr

def _parse_constant_expression(self, in_template: bool) -> ASTExpression:
    # -> conditional-expression ->
    #    logical-or-expression
    #  | logical-or-expression "?" expression ":" assignment-expression
    or_expr = self._parse_logical_or_expression(in_template=in_template)
    cond_expr = self._parse_conditional_expression_tail(or_expr, in_template)
    if cond_expr is not None:
        return cond_expr
    return or_expr

def _parse_expression(self) -> ASTExpression:
    # -> assignment-expression
    #  | expression "," assignment-expression
    exprs = [self._parse_assignment_expression(in_template=False)]
    while True:
        self.skip_ws()
        if not self.skip_string(','):
            break
        exprs.append(self._parse_assignment_expression(in_template=False))
    if len(exprs) == 1:
        return exprs[0]
    else:
        return ASTCommaExpr(exprs)

def _parse_expression_fallback(
    self, end: list[str], parser: Callable[[], ASTExpression], allow: bool = True
) -> ASTExpression:
    # Stupidly "parse" an expression.
    # 'end' should be a list of characters which ends the expression.

    # first try to use the provided parser
    prev_pos = self.pos
    try:
        return parser()
    except DefinitionError as e:
        # some places (e.g., template parameters) we really don't want to use fallback,
        # and for testing we may want to globally disable it
        if not allow or not self.allowFallbackExpressionParsing:
            raise
        self.warn(
            'Parsing of expression failed. Using fallback parser.'
            ' Error was:\n%s' % e
        )
        self.pos = prev_pos
    # and then the fallback scanning
    assert end is not None
    self.skip_ws()
    start_pos = self.pos
    if self.match(_string_re):
        value = self.matched_text
    else:
        # TODO: add handling of more bracket-like things, and quote handling
        brackets = {'(': ')', '{': '}', '[': ']', '<': '>'}
        symbols: list[str] = []
        while not self.eof:
            if len(symbols) == 0 and self.current_char in end:
                break
            if self.current_char in brackets:
                symbols.append(brackets[self.current_char])
            elif len(symbols) > 0 and self.current_char == symbols[-1]:
                symbols.pop()
            self.pos += 1
        if len(end) > 0 and self.eof:
            self.fail(
                'Could not find end of expression starting at %d.' % start_pos
            )
        value = self.definition[start_pos : self.pos].strip()
    return ASTFallbackExpr(value.strip())

